"""Writes the PNG pictures that tests/suite/graphics_png_pixels.bb loads into tests/suite/images/png.

Every picture is 8 by 4 pixels with a left half and a right half, written with every combination of color type and bit depth
that PNG has, and interlaced as well. The color ones are red on the left and blue on the right, the grey ones white and black.
The ones with alpha are opaque on the left and fully see-through on the right.

Usage: generate_png_fixtures.py <output folder>
"""
import struct
import sys
import zlib
from pathlib import Path

WIDTH, HEIGHT = 8, 4

ADAM7 = [(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)]


def chunk(kind, data):
    body = kind + data
    return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body))


def pack_row(samples, depth):
    """The samples of one row as bytes, packed the way the bit depth says."""
    if depth == 8:
        return bytes(samples)
    if depth == 16:
        return b"".join(struct.pack(">H", s) for s in samples)
    out = bytearray()
    for i in range(0, len(samples), 8 // depth):
        byte = 0
        for j in range(8 // depth):
            s = samples[i + j] if i + j < len(samples) else 0
            byte |= s << (8 - depth * (j + 1))
        out.append(byte)
    return bytes(out)


def write_png(path, ctype, depth, pixel, interlace=False, palette=None, trns=None):
    """pixel(x) gives the samples of a pixel in the left or the right half, as a tuple."""

    def rows_of(xs, ys):
        raw = bytearray()
        for y in ys:
            samples = [s for x in xs for s in pixel(x)]
            raw += b"\x00" + pack_row(samples, depth)
        return bytes(raw)

    if interlace:
        raw = b""
        for x0, y0, dx, dy in ADAM7:
            xs = list(range(x0, WIDTH, dx))
            ys = list(range(y0, HEIGHT, dy))
            if xs and ys:
                raw += rows_of(xs, ys)
    else:
        raw = rows_of(range(WIDTH), range(HEIGHT))
    out = b"\x89PNG\r\n\x1a\n"
    out += chunk(b"IHDR", struct.pack(">IIBBBBB", WIDTH, HEIGHT, depth, ctype, 0, 0, 1 if interlace else 0))
    if palette:
        out += chunk(b"PLTE", b"".join(bytes(c) for c in palette))
    if trns is not None:
        out += chunk(b"tRNS", bytes(trns) if not isinstance(trns, bytes) else trns)
    out += chunk(b"IDAT", zlib.compress(raw))
    out += chunk(b"IEND", b"")
    Path(path).write_bytes(out)


def main():
    out = Path(sys.argv[1])
    out.mkdir(parents=True, exist_ok=True)
    left = lambda x: x < WIDTH // 2

    for depth in (8, 16):
        top = (1 << depth) - 1
        rgb = lambda x, top=top: (top, 0, 0) if left(x) else (0, 0, top)
        rgba = lambda x, top=top: (top, 0, 0, top) if left(x) else (0, 0, top, 0)
        write_png(out / f"rgb{depth}.png", 2, depth, rgb)
        write_png(out / f"rgba{depth}.png", 6, depth, rgba)
        # Pictures with a transparent color key, which is blue.
        key = struct.pack(">HHH", 0, 0, top)
        write_png(out / f"rgb{depth}_key.png", 2, depth, rgb, trns=key)
    write_png(out / "rgba8_interlaced.png", 6, 8, lambda x: (255, 0, 0, 255) if left(x) else (0, 0, 255, 0), interlace=True)
    write_png(out / "rgb8_interlaced.png", 2, 8, lambda x: (255, 0, 0) if left(x) else (0, 0, 255), interlace=True)

    for depth in (1, 2, 4, 8, 16):
        top = (1 << depth) - 1
        grey = lambda x, top=top: (top,) if left(x) else (0,)
        write_png(out / f"grey{depth}.png", 0, depth, grey)
        write_png(out / f"grey{depth}_interlaced.png", 0, depth, grey, interlace=True)
    for depth in (8, 16):
        top = (1 << depth) - 1
        write_png(out / f"grey_alpha{depth}.png", 4, depth, lambda x, top=top: (top, top) if left(x) else (0, 0))

    # Pictures with a palette: red is 0 and blue is 1, which has no alpha or is see-through in the second form.
    colors = [(255, 0, 0), (0, 0, 255)]
    for depth in (1, 2, 4, 8):
        index = lambda x: (0,) if left(x) else (1,)
        write_png(out / f"palette{depth}.png", 3, depth, index, palette=colors)
        write_png(out / f"palette{depth}_alpha.png", 3, depth, index, palette=colors, trns=bytes([255, 0]))
    write_png(out / "palette8_interlaced.png", 3, 8, lambda x: (0,) if left(x) else (1,), interlace=True, palette=colors, trns=bytes([255, 0]))


if __name__ == "__main__":
    main()
